// @name JSX: Clock
// @background #0b1020
// @refresh 1
// An analog clock drawn as a JSX <svg>: no markup is built or parsed.
// `at` (a field) pins the time, for a snapshot; empty, it is the clock.
const C = 240
const at = (angle, r) => [C + r * Math.sin(angle), C - r * Math.cos(angle)]
const Hand = ({ angle, from, to, width, color }) => {
  const [x1, y1] = at(angle, from)
  const [x2, y2] = at(angle, to)
  return <line x1={x1} y1={y1} x2={x2} y2={y2} stroke={color} strokeWidth={width} strokeLinecap="round" />
}
const days = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT']

export function get(app) {
  const now = app.config.at ? new Date(app.config.at) : new Date()
  const s = now.getSeconds()
  const m = now.getMinutes() + s / 60
  const h = (now.getHours() % 12) + m / 60
  const tau = Math.PI * 2
  return (
    <svg width={480} height={480} viewBox="0 0 480 480">
      <rect x={0} y={0} width={480} height={480} fill="#0b1020" />
      <circle cx={C} cy={C} r={220} fill="#131c38" />
      <circle cx={C} cy={C} r={220} fill="none" stroke="#2a3a6b" strokeWidth={4} />
      {Array.from({ length: 60 }).map((_, i) => (
        <Hand angle={(i * tau) / 60} from={i % 5 === 0 ? 178 : 194} to={204}
          width={i % 5 === 0 ? 6 : 2} color={i % 5 === 0 ? '#e2e8f0' : '#475569'} />
      ))}
      <rect x={C + 52} y={C - 18} width={88} height={36} rx={8} fill="#0b1020" />
      <text x={C + 96} y={C + 9} fontSize={24} fill="#fbbf24" textAnchor="middle">{`${days[now.getDay()]} ${now.getDate()}`}</text>
      <Hand angle={(h * tau) / 12} from={-16} to={110} width={12} color="#e2e8f0" />
      <Hand angle={(m * tau) / 60} from={-20} to={170} width={8} color="#e2e8f0" />
      <Hand angle={(s * tau) / 60} from={-30} to={186} width={3} color="#f97316" />
      <circle cx={C} cy={C} r={9} fill="#f97316" />
      <circle cx={C} cy={C} r={3} fill="#0b1020" />
    </svg>
  )
}
